    if len(arr) == 0 or x < arr[0] or x >= arr[-1]:
        raise IndexError("The array is empty or the query is outside the array values.")

    low = 0
    high = len(arr) - 1

    while low <= high:
        mid = (low + high) // 2
        if x < arr[mid]:
            high = mid - 1
        elif x >= arr[mid+1]:
            low = mid + 1
        else:
            return mid

