"""
Computes the differentially private percentile of an array.

Parameters:
    array (array-like): An array containing numbers whose percentile is sought.
    percent (float or array-like): The percentile or list of percentiles sought. Each percentile must be in the range [0, 100]. If percent is array-like, percentiles are returned over the flattened array.
    epsilon (float, default: 1.0): The privacy parameter epsilon. Differential privacy is achieved over the entire output, with epsilon split evenly between each output value.
    bounds (tuple, optional): The bounds of the values of the array, in the form (min, max).
    axis (None or int or tuple of ints, optional): The axis or axes along which the sum is performed. The default, axis=None, sums all the elements of the input array. If axis is negative, it counts from the last to the first axis. If axis is a tuple of ints, a sum is performed on all the specified axes.
    keepdims (bool, default: False): If True, the axes which are reduced are left in the result as dimensions with size one. With this option, the result will broadcast correctly against the input array.
    random_state (int or RandomState, optional): Controls the randomness of the algorithm. To obtain deterministic behavior during randomization, random_state has to be fixed to an integer.
    accountant (BudgetAccountant, optional): An accountant to keep track of the privacy budget.
    unused_args: Should warn the user if any other parameters are passed.

Returns:
    ndarray: Returns a new array containing the percentile values.
"""
# Check input arguments
if not isinstance(percent, (float, np.float64)):
    raise ValueError("Percent must be a float or a list of floats")
if percent < 0 or percent > 100:
    raise ValueError("Percent must be in the range [0, 100]")
if not isinstance(epsilon, (float, np.float64)):
    raise ValueError("Epsilon must be a float")
if epsilon < 0:
    raise ValueError("Epsilon must be non-negative")
if bounds is not None:
    if len(bounds) != 2:
        raise ValueError("Bounds must be a length 2 tuple")
    if not isinstance(bounds[0], (int, np.integer)) or not isinstance(
        bounds[1], (int, np.integer)
    ):
        raise ValueError("Bounds must contain integers")
if axis is not None:
    if not isinstance(axis, int) and not isinstance(axis, tuple):
        raise ValueError("Axis must be an integer or a tuple of integers")
    if axis < -len(array.shape) or (axis >= len(array.shape) and axis != -1):
        raise ValueError("Axis must be within the bounds of the input array")
if not isinstance(keepdims, bool):
    raise ValueError("Keepdims must be a boolean value")
if random_state is not None:
    if not isinstance(random_state, int) and not isinstance(
        random_state, np.random.RandomState
    ):
        raise ValueError(
            "Random state must be an integer or an instance of RandomState"
        )
if accountant is not None:
    if not isinstance(accountant, BudgetAccountant):
        raise ValueError("Accountant must be an instance of BudgetAccountant")

# Calculate the percentile value
percentile_value = np.percentile(array, percent / 100, axis=axis, keepdims=keepdims)

# Validate the calculated value
if bounds is not None:
    if percentile_value < bounds[0] or percentile_value > bounds[1]:
        raise ValueError(
            "Percentile value must be within the bounds of the input array"
        )

# Return the percentile value
return percentile_value

