def add_file(self, path, entry_point=None):
    file = None
    if os.path.isabs(path) or os.path.exists(path):
        # Add the file to the bundle
        file = self.add_path(path)
    elif path in os.environ["PATH"]:
        # Get the absolute path of the binary
        binary_path = Path(os.environ["PATH"]).joinpath(path).resolve()
        if binary_path.is_file():
            # Add the file to the bundle
            file = self.add_path(binary_path)
    else:
        # Try to add the file as a relative path
        relative_path = os.path.join(self.path, path)
        if os.path.exists(relative_path):
            # Add the file to the bundle
            file = self.add_path(relative_path)

    # If the file is an ELF binary, add its dependencies recursively
    if file and file.is_elf:
        for dep in file.dependencies:
            self.add_file(dep, entry_point=entry_point)

    return file

