def read(self, size):
    if not isinstance(size, int):
        raise TypeError("size must be an integral type")
    if size < 0:
        raise ValueError("Size must be positive")
    if size == 0:
        return b""

    buffer = bytearray()
    while len(buffer) < size:
        data = self.stream.read(size - len(buffer))
        if not data:
            break
        buffer.extend(data)

    ret, rest = buffer[:size], buffer[size:]
    self.stream.push(rest)
    self.length -= size
    return bytes(ret)

