"""
Retrieves the quota roots and associated quotas for a given mailbox from the IMAP server.

:param self: An instance of the IMAPClient class.
:param mailbox: The name of the mailbox to retrieve the quota roots for.
:return: A tuple containing the MailboxQuotaRoots object, which represents the quota roots, and a list of Quota objects, which represent the associated quotas.
"""
# Send the appropriate IMAP command to the server
status, response = self._imap4_command("GETQUOTAROOT", mailbox)
if not status:
    raise imapclient.IMAPClientError(
        f"Could not get quota root for {mailbox}: {response}"
    )

# Parse the response to extract the quota roots and quotas
quota_roots = []
quota_root_names = {}
for line in response:
    if not line.startswith("* QUOTAROOT"):
        continue
    root, name = line[10:].strip().split(None, 1)
    quota_roots.append(root)
    quota_root_names[root] = name
if not quota_roots:
    raise imapclient.IMAPClientError(f"No quota roots found for {mailbox}")

quotas = []
for root in quota_roots:
    status, response = self._imap4_command("GETQUOTA", f'"{root}"')
    if not status:
        raise imapclient.IMAPClientError(
            f"Could not get quota for {mailbox}: {response}"
        )
    for line in response:
        if not line.startswith("* QUOTA"):
            continue
        root, mailbox, limit = line[8:].strip().split()[:3]
        quotas.append(Quota(root=root, mailbox=mailbox, limit=int(limit)))

return (
    MailboxQuotaRoots(
        quota_roots=tuple(quota_roots), quota_root_names=tuple(quota_root_names)
    ),
    quotas,
)

