    if not isinstance(size, (int, long)):
        raise TypeError("size parameter must be an int or long.")

    if size == 0:
        return b""
    elif size < 0:
        size = None

    self.seek_to_end()

    if size is None and self.buffer:
        data = self.read_buffer()
        self.reset_buffer()
        return data
    elif size is None:
        chunk = self.get_chunk()
        if chunk:
            return chunk
        else:
            data = self.read_buffer()
            self.reset_buffer()
            return data
    else:
        while len(self.buffer) < size:
            chunk = self.get_chunk()
            if chunk:
                self.write_to_buffer(chunk)

        data = self.read_from_buffer(size)
        remaining_data = self.reset_buffer()
        return data + remaining_data

