    self, n_past, mu, var, X, random_state, sample_weight=None, n_noisy=None
):
    total_mu = mu.copy()
    total_var = var.copy()

    for i in range(len(X)):
        x = X[i]
        if sample_weight is not None:
            weight = sample_weight[i]
        else:
            weight = 1
        n_current = n_past + weight

